# area: narrowing_builtin
# hypothesis: An aliased None check on an attribute stays in effect after box.x is reassigned at the end of a while-loop body, so the next iteration wrongly narrows box.x to int.
from dataclasses import dataclass


@dataclass
class Box:
    x: int | None


def run(box: Box) -> int:
    has_value = box.x is not None
    total = 0
    n = 0
    while n < 2:
        n += 1
        if has_value:
            total += box.x + 1  # expect-error
        box.x = None
    return total


def run_safe(box: Box) -> int:
    total = 0
    n = 0
    while n < 2:
        n += 1
        x = box.x
        has_value = x is not None
        if has_value:
            total += x + 1
        box.x = None
    return total


try:
    print(run(Box(3)))
except TypeError as exc:
    print('TypeError:', exc)

print(run_safe(Box(3)))
